We consider a system subject to three degradation processes $\left\{X_1(t), t \geq 0\right\}$, $\left\{X_2(t), t \geq 0\right\}$ and $\left\{X_3(t), t \geq 0\right\}$, respectively. These degradation processes start at random times according to a homogeneous Poisson process with parameter $\lambda=1$. The degradation processes develop according to non-homogeneous gamma process with parameters $\alpha_1=1.1$, $\beta_1=1.1$, $\alpha_2=1.2$, $\beta_2=1.2$ and $\alpha_3=1.3$, $\beta_3=1.3$. Figure \ref{complexgamma} shows these degradation processes and the process $Y(t)=\sum_{j=1}^{3} b_j X_j(t)$ with $b_1=1$, $b_2=0.8$, and $b_3=0.9$. 

\begin{figure}
	\begin{center}
		\includegraphics[width=0.45\textwidth]{complexgamma.eps}
		\caption{Degradation processes and a linear combination} \label{complexgamma}
	\end{center}
\end{figure}

\label{lemacondicion} The conditional probability $f_{U(t)|Y(t)}(y,z)$ is given by
	\begin{align}   
	f_{U(t)|Y(t)}(y,u)
	&=\frac{1}{4\pi^2 g_{Y(t)}(y)} \int_{-\infty}^{\infty}
	\int_{-\infty}^{\infty} \left( \prod_{k=1}^n (1-i(b_k t_1 +c_k t_2)  \beta_k)^{-\alpha_k(t)} \right) e^{-it_1 y-it_2 u} \d t_1\d t_2.
	\end{align}   	\label{ConditionalProbability}

\cite{Lam}
	Given a sequence of non-negative random variables $\{X_j,j=1,2, \dots\}$, if they are independent and the cdf of $X_j$ is given by $F(a^{j-1}x)$ for $j=1,2, \dots$, where $a$ is a positive constant, then $\{X_j,j=1,2,\cdots\}$ is called a geometric process (GP). 
	\label{GP}

\label{lemma1} If $\alpha_k(T)$ is convex in $T$ for all $k$ with $\alpha_k(0)=0$ and $\alpha_k'(0)<\infty$, then 
\begin{itemize}
\item $\mathrm{CV}(N,T)$ is increasing in $T$ for fixed $N$, and  
\item $\mathrm{CV}(N,T)$ is increasing in $N$ for fixed $T$. 
\end{itemize}
